import{_ as e,o as i,c as a,a0 as t}from"./chunks/framework.BdKrsJIB.js";const c=JSON.parse('{"title":"Your first release","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/first-release.md","filePath":"tutorials/first-release.md"}'),l={name:"tutorials/first-release.md"};function n(h,s,r,p,o,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="your-first-release" tabindex="-1">Your first release <a class="header-anchor" href="#your-first-release" aria-label="Permalink to &quot;Your first release&quot;">​</a></h1><p>This tutorial cuts a real release of a small repo using only <code>tarsi-serve</code>. It assumes <code>tarsi-serve</code> is on your PATH (see <a href="/tarsi/getting-started.html">Getting started</a>) and the repo uses conventional commits.</p><h2 id="_1-prepare-the-repo" tabindex="-1">1. Prepare the repo <a class="header-anchor" href="#_1-prepare-the-repo" aria-label="Permalink to &quot;1. Prepare the repo&quot;">​</a></h2><p>The repo needs a <code>tarsi.toml</code>. The minimal useful one:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># tarsi.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">publish</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">crates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">publish</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ghreleases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>Tag-only releases are the org convention (ADR-0004); without the <code>enabled = false</code> lines both publish targets default to on. Units default to cargo workspace members — for a non-cargo repo, declare them explicitly (see <a href="/tarsi/how-to/write-tarsi-toml.html">Write a tarsi.toml</a>).</p><p>Make sure the history you want released is conventional:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># feat(api): add retries        → minor bump</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># fix(core): handle empty body  → patch bump</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># chore: tidy imports           → no release on its own</span></span></code></pre></div><h2 id="_2-plan" tabindex="-1">2. Plan <a class="header-anchor" href="#_2-plan" aria-label="Permalink to &quot;2. Plan&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Read the result. Each unit in <code>plan.units</code> carries:</p><ul><li><code>spec</code> — resolved unit (name, path, tag format, publish targets)</li><li><code>bump</code> — <code>major</code> / <code>minor</code> / <code>patch</code> / <code>none</code></li><li><code>new_version</code> — the version the bump would write</li><li><code>tag</code> — e.g. <code>my-unit-v1.2.0</code></li><li><code>releases</code> — whether this unit actually releases</li><li><code>changelog_markdown</code> — the rendered changelog section</li><li><code>commits</code> — how many commits were attributed</li></ul><p><code>plan.unattributed</code> lists commits that matched no unit&#39;s paths — repo-root files land there. <code>plan.steps</code> is the mutation sequence <code>release</code> would run.</p><p>Nothing has been written. This is the review gate — always <code>plan</code> before <code>release</code>.</p><h2 id="_3-preview-the-notes" tabindex="-1">3. Preview the notes <a class="header-anchor" href="#_3-preview-the-notes" aria-label="Permalink to &quot;3. Preview the notes&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changelog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # per-unit {unit, version, tag, markdown}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # concatenated release notes</span></span></code></pre></div><h2 id="_4-dry-run-the-release" tabindex="-1">4. Dry-run the release <a class="header-anchor" href="#_4-dry-run-the-release" aria-label="Permalink to &quot;4. Dry-run the release&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p><code>release</code> is <strong>dry-run by default</strong> — this executes the full plan and runs every publish target in dry-run mode, reporting what <em>would</em> happen, and writes nothing. Equivalently over ndjson:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;release&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dry_run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><h2 id="_5-release-for-real" tabindex="-1">5. Release for real <a class="header-anchor" href="#_5-release-for-real" aria-label="Permalink to &quot;5. Release for real&quot;">​</a></h2><p>Only after the plan looks right and a human approves:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span></span></code></pre></div><p><code>--yes</code> is <code>dry_run:false</code>. The mutation phase, in order:</p><ol><li>Write <code>CHANGELOG.md</code> sections per releasing unit (created files are tracked for rollback).</li><li>Bump versions in manifests via <code>toml_edit</code> (comments preserved).</li><li>Stage only the touched files — <code>CHANGELOG.md</code>/<code>Cargo.toml</code> per unit plus root manifests — never <code>git add -A</code>.</li><li>Commit <code>chore(release): bump versions</code>.</li><li>Tag each releasing unit (<code>{unit}-v{version}</code>).</li><li><strong>Push branch + tags before publishing</strong> — GitHub Releases auto-creates tags at remote HEAD otherwise.</li><li>Run publish targets (crates.io, GitHub Releases) against the pushed commit.</li></ol><p>The result reports <code>steps_run</code>, per-target <code>publish</code> reports, and — on failure — <code>rolled_back</code> or a manual-cleanup note for partial publishes.</p><h2 id="_6-verify" tabindex="-1">6. Verify <a class="header-anchor" href="#_6-verify" aria-label="Permalink to &quot;6. Verify&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*-v*&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tail</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tarsi-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # now: nothing to release</span></span></code></pre></div><p>The latest-tag-per-unit range means a second <code>plan</code> finds no new commits since the tags you just pushed.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Layer org conventions with a profile — <a href="/tarsi/how-to/author-release-profile.html">Author a release profile pack</a></li><li>Tune attribution and overrides — <a href="/tarsi/how-to/write-tarsi-toml.html">Write a tarsi.toml</a></li><li>Script it from an agent — <a href="/tarsi/how-to/use-serve-ops.html">Drive tarsi-serve ops</a></li></ul>`,31)])])}const g=e(l,[["render",n]]);export{c as __pageData,g as default};
